package jp.tapmarker;
import java.util.*;
public class HistoryBranchTest {
 static int count;static void check(boolean b,String label){if(!b)throw new AssertionError(label);count++;System.out.println("PASS "+label);}
 static PhaseEngine.Phase phase(String id){PhaseEngine.Phase p=new PhaseEngine.Phase();p.id=id;p.name=id;return p;}
 static PhaseEngine.Watch watch(String id,String previous,String next){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=id;w.condition=PhaseEngine.MATCH;w.regionId="screen";w.reference=new float[]{1,1};w.historyRule=previous;w.nextPhase=next;return w;}
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();PhaseEngine.Region r=new PhaseEngine.Region();r.id="screen";r.name="screen";r.bounds=new float[]{0,0,1,1};e.regions.put(r.id,r);PhaseEngine.Phase hub=phase("hub"),reward=phase("reward"),upgrade=phase("upgrade");e.phases.put(hub.id,hub);e.phases.put(reward.id,reward);e.phases.put(upgrade.id,upgrade);PhaseEngine.Watch startReward=watch("pressReward","","hub"),startUpgrade=watch("pressUpgrade","","hub"),branchReward=watch("rewardBranch","pressReward","reward"),branchUpgrade=watch("upgradeBranch","pressUpgrade","upgrade");reward.watches.add(startReward);upgrade.watches.add(startUpgrade);hub.watches.add(branchReward);hub.watches.add(branchUpgrade);e.enter("hub",0);Map<String,float[]> samples=new HashMap<>();samples.put("screen",new float[]{1,1});check(e.activeRegions().isEmpty(),"unknown history samples no branch region");e.observe(samples,1);check(e.poll()==null,"identical screen with unknown history never taps");e.enter("reward",2);check(e.lastCompletedRule.isEmpty(),"phase entry alone does not invent completed action");e.finish(startReward,3);check(e.lastCompletedRule.equals("pressReward")&&e.sourcePhase.equals("reward"),"completed rule and source phase retained across transition");check(e.activeRegions().size()==1,"matching history activates branch region");e.observe(samples,4);check(e.poll()==branchReward,"same display chooses reward branch after reward action");check(e.poll()==null,"other history branch never queued");e.enter("upgrade",5);e.finish(startUpgrade,6);e.observe(samples,7);check(e.poll()==branchUpgrade,"same display chooses upgrade branch after upgrade action");branchUpgrade.historyPhase="reward";check(!e.eligible(branchUpgrade),"two history selectors require both conditions");branchUpgrade.historyPhase="upgrade";check(e.eligible(branchUpgrade),"matching rule and source phase satisfy AND");e.enter("hub",8);e.observe(samples,9);e.lastCompletedRule="pressReward";check(e.poll()!=branchUpgrade,"queued event rechecked after history change");e.clearHistory();check(e.lastCompletedRule.isEmpty()&&e.sourcePhase.isEmpty(),"reset discards stale action and source history");branchReward.historyRule="missing";check(!e.validate().isEmpty(),"deleted history rule rejected");branchReward.historyRule="pressReward";branchReward.historyPhase="missing";check(!e.validate().isEmpty(),"deleted source phase rejected");branchReward.historyPhase="";check(e.validate().isEmpty(),"valid history branches pass validation");reward.terminal=true;e.enter("reward",10);check(e.terminal(),"explicit final state recognized");check(e.activeRegions().isEmpty(),"final state scans no regions");e.observe(samples,11);check(e.poll()==null,"final state produces no outgoing action");PhaseEngine.Phase end=phase("end");end.terminal=true;e.phases.put(end.id,end);e.enter("end",11);check(e.validate().isEmpty(),"final state needs no outgoing transitions");e.initial="hub";e.enter("upgrade",12);check(e.initial.equals("hub"),"runtime state changes do not overwrite configured start state");System.out.println("TOTAL "+count+" history checks passed; Android UI and gestures not tested.");}
}
